class i{constructor(t){this._stringToNumber={},this._numberToString=[];for(let r=0;r<t.length;r++){const e=t[r];this._stringToNumber[e]=r,this._numberToString[r]=e}}encode(t){return this._stringToNumber[t]}decode(t){if(t>=this._numberToString.length)throw new Error(`Out of bounds. Index requested n=${t} can't be >= this._numberToString.length ${this._numberToString.length}`);return this._numberToString[t]}}export{i as DictionaryCoder};
